INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261104-michigan-el-sayed', 'abdul-el-sayed-wins-michigan-senate-first-muslim-senator', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Abdul El-Sayed beats Mike Rogers in Michigan, becoming the first Muslim elected to the U.S. Senate', 'The progressive Democrat and public health doctor keeps Gary Peters'' open seat for his party in a state Trump carried by two points in 2024.', 'Democrat Abdul El-Sayed defeated Republican former Rep. Mike Rogers in Michigan''s open Senate race on Tuesday, Nov. 3, according to the Associated Press, as reported by TIME.

El-Sayed is the first Muslim elected to the U.S. Senate, TIME reported. The seat opened when Democratic Sen. Gary Peters retired. President Trump carried Michigan by two points in 2024.

## Who is Abdul El-Sayed

According to TIME:

- He is 42, the son of Egyptian immigrants, and grew up in suburban Detroit.
- He studied at the University of Michigan, was a Rhodes Scholar at Oxford and earned a medical degree from Columbia.
- He taught epidemiology at Columbia and later led public health departments in Detroit and Wayne County.
- He ran for governor of Michigan in 2018 and lost.

## How he got here

El-Sayed narrowly beat Rep. Haley Stevens in the August primary. Two days before the general election, Stevens endorsed Rogers and appeared with him at a Detroit church, TIME reported.

His win helps give Democrats their new Senate majority. Al Jazeera reported that Democrats had won 53 seats and led in three more early on Wednesday, Nov. 4.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/The_Michigan_state_capitol_in_Lansing_at_dusk_LCCN2020722934.tif/lossy-page1-1280px-The_Michigan_state_capitol_in_Lansing_at_dusk_LCCN2020722934.tif.jpg', 'The Michigan State Capitol in Lansing at dusk (file). Photo: Carol M. Highsmith / Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-04-results.sql', 7, 0, 'newsroom-assistant', '2026-11-04T11:30:00.000Z', '2026-11-04T11:30:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261104-michigan-el-sayed-src1', 'bd-20261104-michigan-el-sayed', 'Abdul El-Sayed Wins Michigan Senate Race', 'https://time.com/article/2026/11/03/abdul-el-sayed-michigan-senate-2026-midterm-elections-mike-rogers/', 'TIME', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-04T11:30:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-04. Editor to confirm.', 'newsroom-assistant', '2026-11-04T11:30:00.000Z');
