INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261104-new-hampshire-pappas', 'chris-pappas-defeats-john-sununu-new-hampshire-senate', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Chris Pappas defeats John E. Sununu to keep New Hampshire''s Senate seat with Democrats', 'The congressman wins the seat Sen. Jeanne Shaheen is leaving, beating the former senator who lost it to her in 2008.', 'Democratic Rep. Chris Pappas beat former Republican Sen. John E. Sununu in New Hampshire''s Senate race on Tuesday, Nov. 3, CBS News projected, keeping the seat in Democratic hands after Sen. Jeanne Shaheen''s retirement.

## The candidates

- **Pappas,** 46, has served in the U.S. House since 2019 and belongs to the bipartisan Problem Solvers Caucus, CBS News reported.
- **Sununu,** 62, is the son of former Gov. John H. Sununu and the brother of former Gov. Chris Sununu. He served in the House and the Senate before losing his Senate seat to Shaheen in 2008. He campaigned on keeping his distance from President Trump.

New Hampshire was one of the Democratic-held seats Republicans had targeted. The Boston Globe listed it among the seats Democrats held on the way to a Senate majority.

CBS News did not report vote totals at the time of its projection. Results for New Hampshire''s governor''s race and its two House seats were still being counted when this story was written early on Wednesday, Nov. 4.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/The_state_capitol_in_Concord,_New_Hampshire_LCCN2017884898.tif/lossy-page1-1280px-The_state_capitol_in_Concord,_New_Hampshire_LCCN2017884898.tif.jpg', 'The New Hampshire State House in Concord (file). Photo: Carol M. Highsmith / Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-04-results.sql', 7, 0, 'newsroom-assistant', '2026-11-04T11:30:00.000Z', '2026-11-04T11:30:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261104-new-hampshire-pappas-src1', 'bd-20261104-new-hampshire-pappas', 'Chris Pappas wins New Hampshire 2026 Senate election', 'https://www.cbsnews.com/news/new-hampshire-2026-senate-pappas-sununu/', 'CBS News', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-04T11:30:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-04. Editor to confirm.', 'newsroom-assistant', '2026-11-04T11:30:00.000Z');
