INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261104-ballot-measures-results', 'ballot-measure-results-2026-virginia-abortion-missouri-voter-id-california-billionaire-tax', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Ballot measures: Virginia adds abortion rights, Missouri rejects a repeal, and voter ID passes in Ohio and North Carolina', 'California''s one-time tax on billionaires trailed in early returns. Results in Arizona and Nevada were still being counted.', 'Voters in dozens of states decided ballot measures on Tuesday, Nov. 3. Here is where the most-watched questions stood early on Wednesday, Nov. 4, according to Just the News.

## Abortion

- **Virginia, Question 1:** Passed. It adds a right to make and carry out reproductive care decisions to the state''s Bill of Rights, with roughly 62% support, based on a New York Times projection Just the News cited.
- **Missouri, Amendment 3:** Failed, the Associated Press projected. It would have repealed the abortion-rights amendment voters approved in 2024 and restricted abortion again.

## Voter ID

- **Ohio, Issue 3:** Passed. It writes photo ID requirements into the state constitution.
- **North Carolina:** A photo ID amendment covering all voters, including mail voters, passed with about 60%.
- **Arizona, Proposition 144,** which pairs voter ID with citizenship checks, and **Nevada, Question 7,** which needed a second approval after passing in 2024, were not yet called.

## Taxes

- **California, Proposition 40:** A one-time 5% tax on residents worth more than $1 billion trailed 43% to 57% in early returns and had not been called.
- **Florida, Amendment 3:** Passed with 62%. It raises the homestead exemption from non-school property taxes and halves the cap on yearly assessment increases for commercial property, rentals and second homes.

Massachusetts results for its nine questions are in a separate Boston Daily story. Counts in several states were still partial, and official results come from each state''s election office.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/View_of_downtown_Sacramento,_California%27s_capital_city,_from_across_the_Sacramento_River_LCCN2013630960.tif/lossy-page1-1280px-View_of_downtown_Sacramento,_California%27s_capital_city,_from_across_the_Sacramento_River_LCCN2013630960.tif.jpg', 'Downtown Sacramento, California''s capital, seen from across the Sacramento River (file). Photo: Carol M. Highsmith / Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-04-results.sql', 7, 0, 'newsroom-assistant', '2026-11-04T11:30:00.000Z', '2026-11-04T11:30:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261104-ballot-measures-results-src1', 'bd-20261104-ballot-measures-results', '2026 ballot measure results: Voters decide on abortion, voter ID and tax questions across states', 'https://justthenews.com/politics-policy/elections/2026-ballot-measure-results-voters-decide-abortion-voter-id-and-tax', 'Just the News', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-04T11:30:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-04. Editor to confirm.', 'newsroom-assistant', '2026-11-04T11:30:00.000Z');
