INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261104-alaska-senate-count', 'alaska-senate-sullivan-peltola-too-close-ranked-choice-november-18', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Alaska''s Senate race between Dan Sullivan and Mary Peltola is too close to call', 'Sullivan led 48.6% to 47.4% with about 70% of precincts in. If no one reaches 50%, ranked-choice tabulation is set for Wednesday, Nov. 18.', 'Alaska''s Senate race between Republican Sen. Dan Sullivan and Democrat Mary Peltola was still undecided early on Wednesday, Nov. 4.

With about 70% of precincts reporting on the night of Tuesday, Nov. 3, Sullivan had 48.6% and Peltola 47.4%, Alaska Public Media reported. A second candidate named Dan J. Sullivan had 1.7%.

## What happens next

- Alaska accepts mailed ballots for 10 days after the election, or 15 days for ballots mailed from overseas, according to Alaska Public Media.
- If no candidate wins more than 50% of first-choice votes, the state will run its ranked-choice tabulation on Wednesday, Nov. 18.

## The second Dan Sullivan

Dan J. Sullivan, a retired teacher from Petersburg, has been the subject of a Justice Department lawsuit and a criminal investigation, Alaska Public Media reported. A judge dismissed the lawsuit, which sought to block certification if Sen. Sullivan lost, and the Justice Department is appealing. The U.S. attorney said he was not assuming a crime had occurred. Peltola has denied knowing about any plan involving the second candidate.

Democrats had already won a Senate majority without Alaska, Al Jazeera and the Boston Globe reported.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/State_Capitol,_front_elevation_detail,_Juneau,_Alaska_LCCN2010630417.tif/lossy-page1-1280px-State_Capitol,_front_elevation_detail,_Juneau,_Alaska_LCCN2010630417.tif.jpg', 'The front of the Alaska State Capitol in Juneau (file). Photo: Carol M. Highsmith / Library of Congress via Wikimedia Commons, public domain', 'public_domain', 'newsroom', 'content/2026-11-04-results.sql', 6, 0, 'newsroom-assistant', '2026-11-04T11:30:00.000Z', '2026-11-04T11:30:00.000Z');
